import { API_BASE_URL } from '../config/api';

export type PlanId = 'monthly' | 'yearly' | 'lifetime';

export interface Plan {
  id: PlanId;
  name: string;
  priceCents: number;
  period: string;
  badge?: string;
  features: string[];
}

export const PLANS: Plan[] = [
  { id: 'monthly', name: 'Monthly', priceCents: 1200, period: 'month', features: ['Unlimited agents', 'Cloud sync', 'Priority support'] },
  { id: 'yearly', name: 'Yearly', priceCents: 9900, period: 'year', badge: 'Save 30%', features: ['Everything in Monthly', '2 months free', 'Early features'] },
  { id: 'lifetime', name: 'Lifetime', priceCents: 29900, period: 'once', features: ['Everything, forever', 'All future models', 'Founding badge'] },
];

export async function subscribe(planId: PlanId): Promise<{ subscriptionId: string }> {
  const response = await fetch(`${API_BASE_URL}/subscriptions`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ planId }),
  });
  if (!response.ok) throw new Error(`Subscribe failed with status ${response.status}`);
  return (await response.json()) as { subscriptionId: string };
}

import { useCallback, useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, SafeAreaView, ActivityIndicator, ScrollView } from 'react-native';
import { subscribe, PLANS, type PlanId } from '../services/subscriptions';

const colors = {
  bg: '#0f120e',
  text: '#f5f5f0',
  surface: '#1a1f1a',
  accent: '#f05039',
  muted: '#8a8f8a',
  textMuted: '#a8ada6',
  danger: '#ff6b5e',
  success: '#4ade80',
}

const formatPrice = (cents: number): string => `${(cents / 100).toFixed(0)}`;

export function PlansScreen(): JSX.Element {
  const [selected, setSelected] = useState<PlanId>('yearly');
  const [submitting, setSubmitting] = useState(false);
  const [success, setSuccess] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const onSubscribe = useCallback(async () => {
    setSubmitting(true);
    setError(null);
    try {
      const { subscriptionId } = await subscribe(selected);
      setSuccess(subscriptionId);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Subscription failed.');
    } finally {
      setSubmitting(false);
    }
  }, [selected]);

  return (
    <SafeAreaView style={styles.safe}>
      <ScrollView contentContainerStyle={styles.content}>
        <Text style={styles.title}>Choose your plan</Text>
        {PLANS.map(plan => {
          const active = plan.id === selected;
          return (
            <TouchableOpacity
              key={plan.id}
              style={[styles.plan, active && styles.planActive]}
              onPress={() => setSelected(plan.id)}
              accessibilityRole="button"
              accessibilityLabel={`${plan.name} plan, ${formatPrice(plan.priceCents)} ${plan.period}`}
            >
              <View style={styles.planHeader}>
                <Text style={styles.planName}>{plan.name}</Text>
                {plan.badge && <Text style={styles.badge}>{plan.badge}</Text>}
              </View>
              <Text style={styles.price}>
                ${formatPrice(plan.priceCents)}<Text style={styles.period}> / {plan.period}</Text>
              </Text>
              {plan.features.map(f => (
                <Text key={f} style={styles.feature}>✓ {f}</Text>
              ))}
            </TouchableOpacity>
          );
        })}
        {error && <Text style={styles.error}>{error}</Text>}
        {success && <Text style={styles.success}>Subscribed — {success}</Text>}
        <TouchableOpacity style={styles.cta} onPress={onSubscribe} disabled={submitting} accessibilityRole="button">
          {submitting ? <ActivityIndicator color="{colors.bg}" /> : <Text style={styles.ctaText}>Subscribe</Text>}
        </TouchableOpacity>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  content: { padding: 20 },
  title: { fontSize: 22, fontWeight: '700', color: colors.text, marginBottom: 16 },
  plan: { backgroundColor: colors.surface, borderRadius: 10, padding: 16, marginBottom: 12, borderWidth: 2, borderColor: 'transparent' },
  planActive: { borderColor: colors.accent },
  planHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },
  planName: { color: colors.text, fontWeight: '700', fontSize: 16 },
  badge: { backgroundColor: colors.accent, color: colors.bg, fontSize: 11, fontWeight: '700', borderRadius: 10, paddingHorizontal: 8, paddingVertical: 3, overflow: 'hidden' },
  price: { color: colors.text, fontSize: 28, fontWeight: '800', marginVertical: 8 },
  period: { color: colors.muted, fontSize: 13, fontWeight: '400' },
  feature: { color: colors.textMuted, marginTop: 4 },
  cta: { backgroundColor: colors.accent, borderRadius: 6, paddingVertical: 16, alignItems: 'center', marginTop: 8 },
  ctaText: { color: colors.bg, fontWeight: '700', fontSize: 16 },
  error: { color: colors.danger, marginBottom: 8 },
  success: { color: colors.success, marginBottom: 8 },
});
